import{_ as t,o as a,c as r,a3 as d}from"./chunks/framework.Ch_0qWu9.js";const f=JSON.parse('{"title":"资源访问与分发条件","description":"","frontmatter":{"sourcePath":"docs/licenses/distribution.zh-CN.md","sourceUrl":"https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/distribution.zh-CN.md","alternateUrl":"/TCSExam/docs/licenses/distribution/","alternateAnchors":{"资源访问与分发条件":"resource-access-and-distribution-conditions","对所选材料应用相应条件":"apply-conditions-to-the-selected-material","数据与任务材料":"data-and-task-materials","工具与运行组件":"tools-and-runtime-components","resource-access-and-distribution-conditions":"resource-access-and-distribution-conditions","apply-conditions-to-the-selected-material":"apply-conditions-to-the-selected-material","data-and-task-materials":"data-and-task-materials","tools-and-runtime-components":"tools-and-runtime-components"}},"headers":[],"relativePath":"zh/licenses/distribution/index.md","filePath":"zh/licenses/distribution/index.md"}'),o={name:"zh/licenses/distribution/index.md"};function c(s,e,n,i,l,h){return a(),r("div",null,[...e[0]||(e[0]=[d('<p><a id="resource-access-and-distribution-conditions"></a></p><h1 id="资源访问与分发条件" tabindex="-1">资源访问与分发条件 <a class="header-anchor" href="#资源访问与分发条件" aria-label="Permalink to &quot;资源访问与分发条件&quot;">​</a></h1><p>中文译文供参考，许可条款以原文为准。</p><p>本指南列出 TCSExam 资源的获取途径和共享条件。 供在本地准备数据，或分发源码、数据及镜像的用户阅读。</p><p><a id="apply-conditions-to-the-selected-material"></a></p><h2 id="对所选材料应用相应条件" tabindex="-1">对所选材料应用相应条件 <a class="header-anchor" href="#对所选材料应用相应条件" aria-label="Permalink to &quot;对所选材料应用相应条件&quot;">​</a></h2><p>使用 <a href="/TCSExam/docs/zh/resources/"><code>tcsexam build</code></a> 获取固定官方输入、验证并转换它们，再组装本地镜像。标记为 <code>local_prepare</code> 的资源可按其来源条款在本地准备。<code>private_only</code> 表示该材料不得包含在公开源码导出和公开镜像分发中。</p><p>再分发产物前，遵循下述资源具体条件，并保留所需源码、署名和声明。每行适用于指定材料和版本；镜像需要同时满足全部输入及继承层的条件。本地生成产物保留来源材料适用的限制。精确产物标识和文件范围见链接记录。</p><p><a id="data-and-task-materials"></a></p><h2 id="数据与任务材料" tabindex="-1">数据与任务材料 <a class="header-anchor" href="#数据与任务材料" aria-label="Permalink to &quot;数据与任务材料&quot;">​</a></h2><p>读法说明：逐资源查看。来源链接和记录标明覆盖的输入；共享条件同时适用于生成材料及包含它们的镜像。</p><table tabindex="0"><thead><tr><th>资源</th><th>获取途径与来源</th><th>条款与处理方式</th></tr></thead><tbody><tr><td>原创代码、判分器、脚本和构建配置</td><td>仓库源码</td><td>在项目贡献者拥有相应权利的范围内采用 Apache-2.0。保留作者声明、<code>LICENSE</code> 和 <code>NOTICE</code>，并标明修改。</td></tr><tr><td>原创题面、说明文档和网站内容</td><td>仓库源码和网站仓库</td><td>在项目贡献者拥有相应权利的范围内采用 CC BY 4.0。保留署名并标明修改。</td></tr><tr><td>QBF 评测数据：十三个公开实例和 57 个隐藏变换实例</td><td>Mark Peyrer、Maximilian Heisinger 和 Martina Seidl 的 <a href="https://doi.org/10.5281/zenodo.18832723" target="_blank" rel="noreferrer">ParaProofa v1 补充材料</a>；<a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/qbf-data-distribution-source.json" target="_blank" rel="noreferrer">固定来源记录</a></td><td>CC BY 4.0，署名补充材料作者及原始实例族。三个 BMC 实例 <code>ex018</code>、<code>ex019</code> 和 <code>ex020</code> 还保留 University of Toronto 2007 非商业教学研究条款，包括不收费、声明和宣传条件。固定产物范围列于下方。补充材料中的软件保留自身许可。</td></tr><tr><td>BPPLIB 实例、装箱方案及注册表提取数据</td><td><a href="https://github.com/mdelorme2/BPPLIB" target="_blank" rel="noreferrer">BPPLIB</a> 的固定官方文件；<a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/bpplib-reconstruction.json" target="_blank" rel="noreferrer">准备记录</a></td><td>CC BY-NC-ND 4.0。保留署名、非商业和禁止演绎条件。生成文件和所有包含它们的镜像均限于本地使用，不得放入公开镜像仓库或公开下载。</td></tr><tr><td>PACE 2019 Vertex Cover 公开开发数据</td><td>public-v2 归档的<a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/vc-pace2019-source.json" target="_blank" rel="noreferrer">来源记录</a>；<a href="https://zenodo.org/records/3368306" target="_blank" rel="noreferrer">Zenodo 数据集</a></td><td>M. Ayaz Dzulfikar、Johannes K. Fichte 和 Markus Hecher 的 CC BY 4.0。范围：<code>solver-vc-pace2019-development-data</code>，包含使用 XZ 5.2.5 重新压缩的 100 个奇数编号公开实例。保留 CC BY 文本、<code>PACE2019-VC-NOTICE.txt</code>、来源和 PACE 报告链接、图实例族署名及重新压缩说明。</td></tr><tr><td>PACE 2021 Cluster Editing 公开开发数据</td><td><a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/ce-pace2021-source.json" target="_blank" rel="noreferrer">固定来源与 XZ 重建记录</a></td><td>CC0-1.0 覆盖 <code>solver-ce-pace2021-development-data</code> 中 100 个奇数编号公开实例。附上 CC0 文本和来源记录。</td></tr><tr><td>PACE 2022 Directed Feedback Vertex Set 公开开发数据</td><td><a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/dfvs-pace2022-source.json" target="_blank" rel="noreferrer">固定来源与重建记录</a></td><td>仅限本地准备：官方归档没有数据许可。保留其声明，官方归档、生成实例及包含它们的镜像均不得公开分发。PACE 报告自身采用 CC BY 4.0。</td></tr><tr><td>PACE 2024 OSCM 公开开发数据</td><td><a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/oscm-pace2024-source.json" target="_blank" rel="noreferrer">两个固定官方归档</a></td><td>合并后的 173 文件产物仅限本地使用。MIT 覆盖 60 个中等规模和十三个微型测试集实例；100 个 Exact Track 实例没有数据许可。保留来源声明及测试集 MIT 文本。两个官方归档、合并生成的产物及包含它们的镜像均不得公开分发。准备时排除上游 <code>.sol</code> 文件。</td></tr><tr><td>AHC058 公开开发数据</td><td><a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/ahc058-atcoder-source.json" target="_blank" rel="noreferrer">官方 AtCoder 归档与锁定生成器</a></td><td>仅限本地准备：尚未确定题面、输入、生成器、计分程序或可视化程序的开放再分发许可。保留来源声明。官方归档、生成实例及包含它们的镜像均不得公开分发。</td></tr><tr><td>课程排课实例</td><td><a href="https://github.com/iolab-uniud/cb-ctt" target="_blank" rel="noreferrer">cb-ctt</a> 提供二十个对应实例及变换；<a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/ctt-source-comparison.json" target="_blank" rel="noreferrer">来源比较</a></td><td>原作者提供 CC BY 4.0。标明格式和名称变化，包括 <code>comp15</code> 对应官方 <code>comp03</code>。<code>comp11</code> 和 OptHub 解需要遵循自身来源条款；请从<a href="https://www.eeecs.qub.ac.uk/itc2007/" target="_blank" rel="noreferrer">官方来源</a>获取。其再分发条款尚未确认。</td></tr><tr><td>IWLS 2022 公开真值表</td><td><a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/logic-syn-iwls2023-source.json" target="_blank" rel="noreferrer">固定来源与变换记录</a></td><td>为 100 个公开真值表保留 IWLS 2022 的 MIT 许可，并标明变换。ABC 归档采用下方单列的软件条款。</td></tr><tr><td>MQLib 实例</td><td><a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/mqlib-family-license-review.json" target="_blank" rel="noreferrer">各实例族来源与许可记录</a></td><td>OR-Library 实例 <code>g001642</code>、<code>g002564</code> 和 <code>g002776</code> 有明确的 MIT 许可依据；保留 J. E. Beasley 署名和完整许可证。其他实例族按各自条款从相应来源获取。</td></tr><tr><td>ROADEF/EURO 2012 实例和参考分配方案</td><td><a href="https://github.com/google/or-tools/tree/06376d5ff5bbaead64e9b2df61ccbe74e99e5f8c/data/roadef_challenge_2011/solution_checker" target="_blank" rel="noreferrer">固定 Google OR-Tools 源码</a>；<a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/roadef-hidden-source-chain.json" target="_blank" rel="noreferrer">来源链记录</a></td><td>所含实例和判分器源码采用 Apache-2.0。保留 Google 署名、许可及修改说明。参考分配方案是项目生成的数值输出，单独记录。从<a href="https://www.roadef.org/challenge/2012/en/sujet.php" target="_blank" rel="noreferrer">官方页面</a>获取竞赛 PDF；其再分发条款尚未确认。</td></tr><tr><td>MaxSAT 隐藏数据</td><td><a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/assets/data/solver/solver-maxsat-mse-judging-data-recipe.json" target="_blank" rel="noreferrer">固定官方 Zenodo 归档与重建配方</a></td><td>MaxSAT Evaluation 2026 补充材料采用 CC BY 4.0。保留<a href="/TCSExam/docs/zh/licenses/THIRD_PARTY_NOTICES/#additional-full-materials">第三方声明</a>中的补充材料及实例族署名。所含求解器程序保留自身许可。</td></tr><tr><td>参考答案内容</td><td><a href="/TCSExam/docs/zh/oracle-answers/">参考答案处理</a></td><td>将具体可通过判分的答案保存在模型解题环境之外。默认保持私有，普通构建和运行无需这些答案。对于获准分发的答案产物，应使用显式发布接口，并遵循资源具体条件。</td></tr><tr><td>论文、规则 PDF、模型输出和其他外部材料</td><td>原始来源及各材料具体许可</td><td>遵循所共享材料的条款。软件或数据集许可仅适用于其覆盖的内容。</td></tr></tbody></table><p>固定 QBF 产物范围为 <code>qbf-public</code>、<code>qbf-judging</code>、<code>qbf-qbfeval-online-development</code>、<code>qbf-qbfeval-offline-development</code>、<code>qbf-qbfeval-online-backend</code>、<code>qbf-qbfeval-offline-verifier</code> 和 <code>backend-public-online-qbf-qbfeval</code>。对应的固定变换数据、标准答案及 <code>ex*</code> 映射具有<a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/qbf-data-distribution-source.json" target="_blank" rel="noreferrer">来源记录</a>中记载的数据许可。任何分发产物都应附带适用的软件、系统和逐实例声明，答案内容还应遵循答案处理指南。</p><p><a id="tools-and-runtime-components"></a></p><h2 id="工具与运行组件" tabindex="-1">工具与运行组件 <a class="header-anchor" href="#工具与运行组件" aria-label="Permalink to &quot;工具与运行组件&quot;">​</a></h2><p>读法说明：每行给出组件许可，以及源码或替换要求。</p><table tabindex="0"><thead><tr><th>资源</th><th>获取途径与来源</th><th>条款与处理方式</th></tr></thead><tbody><tr><td>PACE 2021 Cluster Editing 和 PACE 2022 Directed Feedback Vertex Set 判分器</td><td>固定官方 <a href="https://pacechallenge.org/2021/verifier.zip" target="_blank" rel="noreferrer">2021 ZIP</a> 和 <a href="https://pacechallenge.org/2022/verifier.tar.gz" target="_blank" rel="noreferrer">2022 tar.gz</a>，通过本地配方编译</td><td>再分发条款尚未确认。在本地下载和编译，保留上游声明，并将源码快照及生成镜像保持私有。</td></tr><tr><td>VC 公开自测判分器</td><td><code>backend-public-online-vc-pace2019</code> 的<a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/vc-public-judge-image.json" target="_blank" rel="noreferrer">组件要求</a></td><td>保留项目和数据许可、vc_validate 对应源码及构建说明，以及适用的系统包源码材料。</td></tr><tr><td>OSCM NumPy 开发工具</td><td><a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/oscm-pace2024-development-tools-source.json" target="_blank" rel="noreferrer">固定 NumPy 2.2.6 wheel</a></td><td>仅限本地准备。配方验证 wheel 及其 RECORD 条目，并保留四份上游声明。随附依赖的源码义务尚未确认；wheel、工具镜像及包含它们的镜像均保持私有。</td></tr><tr><td>CPSolver、dom4j 和 log4j</td><td><a href="/TCSExam/docs/zh/licenses/cpsolver-source/">源码、构建与替换指南</a></td><td>Java 源码：LGPL-3.0-or-later；原始 Ant 文件：LGPL-2.1-or-later；dom4j：五条款 BSD 风格条款；log4j：Apache Software License 1.1。分发二进制文件时附上要求的对应源码、构建材料和完整声明。</td></tr><tr><td>Qute、drat-trim 和 qrp2rup</td><td><a href="/TCSExam/docs/zh/licenses/THIRD_PARTY_NOTICES/">第三方声明</a>中的固定源码</td><td>Qute 后来添加的 MIT 声明是否适用于较旧快照尚未确认；保留原始版本及版本比较。drat-trim 采用 MIT。qrp2rup 依照作者补充材料采用 CC BY 4.0：署名、标明修改，并随二进制文件提供源码。分别保留 MiniSat 和 docopt.cpp 的 MIT/Boost 声明。</td></tr><tr><td>MQLib 软件</td><td><a href="https://github.com/MQLib/MQLib" target="_blank" rel="noreferrer">MQLib 仓库</a></td><td>MIT。保留版权、许可证及修改声明。实例数据适用上方各实例族条款。</td></tr><tr><td>ABC 源码</td><td><a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/logic-syn-iwls2023-source.json" target="_blank" rel="noreferrer">固定来源记录</a></td><td>保留 UC Regents BSD 风格声明。</td></tr><tr><td>Lean、mathlib、elan 和系统包</td><td><a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/system-license-materials.json" target="_blank" rel="noreferrer">系统来源</a>、<a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/lean-public-rebuild-system-materials.json" target="_blank" rel="noreferrer">附加包描述</a>及 <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/lean-public-rebuild-mathlib-materials.json" target="_blank" rel="noreferrer">mathlib 清单</a></td><td>保留各组件声明，并在许可要求时提供完整对应源码。源码、编译缓存和版本应相互匹配。</td></tr><tr><td>智能体工具</td><td>固定 Harbor 运行时安装器；<a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/claude-code-distribution.json" target="_blank" rel="noreferrer">智能体工具记录</a></td><td>智能体包保留自身许可。记录中的 Claude Code 包声明保留所有权利，没有一般性再分发授权；应在运行时安装，并从分发的环境镜像中排除。</td></tr><tr><td>ProofWidgets 中的 Graphviz 及其他浏览器组件</td><td><a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/proofwidgets-embedded-components.json" target="_blank" rel="noreferrer">内嵌组件记录</a>和 <a href="/TCSExam/docs/zh/environments/lean-base/graphviz-epl/SOURCE-OFFER/">Graphviz 源码材料</a></td><td>Graphviz 采用 EPL-2.0，封装层采用 Apache-2.0。通过 <code>tcsexam source-inputs</code> 准备固定源码归档。保留 EPL 文本、Graphviz 对应源码、封装层修改和构建规则，以及安装在 <code>/usr/share/doc/tcsexam/</code> 下适用的 Lake、浏览器和 npm 声明。</td></tr></tbody></table><p>署名文本见<a href="/TCSExam/docs/zh/licenses/THIRD_PARTY_NOTICES/">第三方声明</a>，固定文件清单见<a href="/TCSExam/docs/zh/licenses/full-review/">组件记录</a>。<a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/assets/files.json" target="_blank" rel="noreferrer">文件清单</a>和<a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/assets/images.json" target="_blank" rel="noreferrer">镜像清单</a>记录输入路径、产物标识和可用获取地址。</p>',18)])])}const p=t(o,[["render",c]]);export{f as __pageData,p as default};
